command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0"
$branch="work/search-content-regex-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before cleanup"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $main){throw "work branch is not the accepted main revision"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "work branch delete failed"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "cleanup prune failed"}
$remaining=(& git branch -r --list ("origin/"+$branch))
if($remaining){throw "deleted work branch still present after prune"}
Write-Host "CONTENT_REGEX_WORK_BRANCH_CLEANUP=PASS"
Write-Host "CONTENT_REGEX_ACCEPTED_MAIN=$main"
